import{_ as o,l as i,o as e,c as s,v as E,p as n,x as r,d as l,i as c,S as C}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"软错误与 ECC 内存","description":"","frontmatter":{"title":"软错误与 ECC 内存","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/soft-error-ecc.md","filePath":"cs/soft-error-ecc.md","lastUpdated":1789023840000}'),d={name:"cs/soft-error-ecc.md"};function A(p,a,h,B,m,D){const t=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=E('<h1 id="软错误与-ecc-内存" tabindex="-1">软错误与 ECC 内存 <a class="header-anchor" href="#软错误与-ecc-内存" aria-label="Permalink to &quot;软错误与 ECC 内存&quot;">​</a></h1><div class="epigraph"><p>粒子打中 SRAM 或 DRAM 电容，比特翻转而晶体管并未损坏；纠错码把可纠正的翻转从故障里分开，扫描测试看不见这一类。</p><footer>—— 据 Baumann, Soft Errors in Advanced Computer Systems, IEEE Micro 2005；Hamming 编码先修；JEDEC 与服务器内存实践 整理</footer></div><p><a href="/cs/bist">上一课</a>抓制造与部分老化硬缺陷。组成课已有<a href="/cs/dram-refresh">DRAM 刷新</a>与<a href="/cs/hamming-code">汉明码</a>。缺口是运行期 <strong>软错误（SER）</strong>：SEU 翻转存储节点，功能上像随机写，扫描链当时可能是好的。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>宇宙射线中子、封装 α 粒子在扩散区产生电荷，SRAM 位单元翻转阈值随工艺变低。DRAM 电容也可被扰，但机制与刷新丢失不同。缺口不是再讲 March 算法，而是：<strong>检测/纠正</strong>要做在数据通路上——ECC 旁路、寄存器文件奇偶、流水线保护。</p><p>SECDED（单纠正双检测）常用于缓存与 DIMM。芯片杀（chipkill）把符号分布到多个颗粒，对照后课 DRAM 组织。本课钉「软错误 ≠ 硬故障」与 ECC 的位置。</p><h3 id="ecc-不是「bist-的另一种签名」" tabindex="-1">ECC 不是「BIST 的另一种签名」 <a class="header-anchor" href="#ecc-不是「bist-的另一种签名」" aria-label="Permalink to &quot;ECC 不是「BIST 的另一种签名」&quot;">​</a></h3><p>BIST 压缩的是测试响应；ECC 是功能数据的冗余，每拍（或每次读）算。把二者合成一种「校验」，会在该不启动 BIST 的功能路径上误插 LFSR。软错误纠正后程序继续；不可纠正则机器检查异常——OS 课再接，本课承认有 UE 信号。</p><p><span class="marginnote">Baumann, <em>IEEE Micro</em>, 2005 是软错误综述名篇。Hamming/SECDED 在信息论课已有。JEDEC DDR 规范含 ECC DIMM 的数据宽度（如 ×72）。本课不编造 FIT 数字表。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>读：数据+校验进译码器，纠正后送 CPU，写回可选。写：编码器生成校验。部分写要先读–改–写以免校验不一致。寄存器与 FF：关键控制用三重化（TMR）或只对地址/状态奇偶。FPU 数据路径是否 ECC 是成本选择。</p>',11)),(e(),n(C,null,{default:r(()=>[c(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20PART%5B%22%E7%B2%92%E5%AD%90%20%2F%20%CE%B1%22%5D%20--%3E%20SEU%5B%22%E5%AD%98%E5%82%A8%E6%AF%94%E7%89%B9%E7%BF%BB%E8%BD%AC%22%5D%0A%20%20SEU%20--%3E%20ECC%5B%22SECDED%20%E8%AF%91%E7%A0%81%22%5D%0A%20%20ECC%20--%3E%20CE%5B%22%E7%BA%A0%E6%AD%A3%E5%B9%B6%E8%AE%B0%E5%BD%95%22%5D%0A%20%20ECC%20--%3E%20UE%5B%22%E4%B8%8D%E5%8F%AF%E7%BA%A0%E6%AD%A3%20%E2%86%92%20%E6%A3%80%E6%9F%A5%E5%BC%82%E5%B8%B8%22%5D%0A%20%20CE%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E8%80%81%E5%8C%96%E6%98%AF%E5%8F%A6%E4%B8%80%E6%97%B6%E9%97%B4%E5%B0%BA%E5%BA%A6%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=E('<p>扫描测试通常不注入粒子；SER 用加速试验与 FIT 模型估计，属可靠性工程，与 ATPG 分家。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>下一课老化（NBTI、电迁移）让延迟漂移，表现为时序违例而非单比特翻转。DRAM 组织课会看到 rank/bank 上的 ECC 布局。本课先把「运行期随机翻转」钉进数字系统课序的可靠性入口。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲辐射加固工艺细节，不把纠错当密码学。不进入量子计算误码。不把 ECC 内存的通道时序写完——那是 DDR 课。</p><p>后课默认：软错误是可恢复或不可纠正的随机位翻转；功能 ECC 与制造 BIST 分工。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>BIST 对硬缺陷；软错误是运行期 SEU。</li><li>SECDED 在读路径纠正并报告；UE 另处理。</li><li>扫描当时通过不保证现场无翻转。</li><li>出处：Baumann, <em>IEEE Micro</em>, 2005；汉明码先修；JEDEC ECC DIMM 实践。</li></ul>',8))])}const f=o(d,[["render",A]]);export{_ as __pageData,f as default};
